import PhotoSwipeLightbox from"https://unpkg.com/photoswipe@5/dist/photoswipe-lightbox.esm.js";import PhotoSwipe from"https://unpkg.com/photoswipe@5/dist/photoswipe.esm.js";document.querySelectorAll(".photoswipegallery").forEach(o=>{new PhotoSwipeLightbox({gallery:o,children:"a",pswpModule:PhotoSwipe,padding:{top:20,bottom:20,left:20,right:20},bgOpacity:.9,showHideAnimationType:"fade"}).init()});